  FIREWALL_NOT_FOUND = 'FIREWALL_NOT_FOUND',
  FIREWALL_ORG_ISOLATION = 'FIREWALL_ORG_ISOLATION',
  FIREWALL_USER_ISOLATION = 'FIREWALL_USER_ISOLATION',
  FIREWALL_SOFT_DELETED = 'FIREWALL_SOFT_DELETED',
  FIREWALL_WRITE_DENIED = 'FIREWALL_WRITE_DENIED',

