  GUARD_FIELD_PROTECTED = 'GUARD_FIELD_PROTECTED',
  GUARD_FIELD_IMMUTABLE = 'GUARD_FIELD_IMMUTABLE',
  GUARD_FIELD_NOT_CREATEABLE = 'GUARD_FIELD_NOT_CREATEABLE',
  GUARD_FIELD_NOT_UPDATABLE = 'GUARD_FIELD_NOT_UPDATABLE',
  GUARD_SYSTEM_MANAGED = 'GUARD_SYSTEM_MANAGED',

  // Validation Layer (400/413)
  VALIDATION_FAILED = 'VALIDATION_FAILED',
