  // existing clients keep working. Cataloged so SDK switches stay exhaustive.
  PAYLOAD_TOO_LARGE = 'PAYLOAD_TOO_LARGE',
  INVALID_JSON = 'INVALID_JSON',
  VALIDATION_ERROR = 'VALIDATION_ERROR',
  // FK existence pre-check (request-time, validation layer — distinct from
