  // Batch Operations (400/207)
  BATCH_SIZE_EXCEEDED = 'BATCH_SIZE_EXCEEDED',
  BATCH_FAIL_FAST_STOPPED = 'BATCH_FAIL_FAST_STOPPED',
  BATCH_MISSING_IDS = 'BATCH_MISSING_IDS',

  // Database Layer (400/409/500) — surfaced when the SQL write itself fails
  // post-validation (constraint violations, generic insert/update failure).
  // Same shape as the other layers so consumers can switch on `code`.
  DB_NOT_NULL_VIOLATION = 'DB_NOT_NULL_VIOLATION',
  DB_UNIQUE_VIOLATION = 'DB_UNIQUE_VIOLATION',
  DB_FOREIGN_KEY_VIOLATION = 'DB_FOREIGN_KEY_VIOLATION',
