  TENANT_SCOPE_MISMATCH = 'TENANT_SCOPE_MISMATCH',
  TENANT_AMBIGUOUS = 'TENANT_AMBIGUOUS',
  TENANT_UNAVAILABLE = 'TENANT_UNAVAILABLE',
  TENANT_OVERLOADED = 'TENANT_OVERLOADED',
  TENANT_DEPTH_EXCEEDED = 'TENANT_DEPTH_EXCEEDED',
  TENANT_ADMISSION_UNAVAILABLE = 'TENANT_ADMISSION_UNAVAILABLE',
  TENANT_LOOKUP_UNAVAILABLE = 'TENANT_LOOKUP_UNAVAILABLE',
  TENANT_LOOKUP_PENDING = 'TENANT_LOOKUP_PENDING',
  TENANT_NOT_PROVISIONED = 'TENANT_NOT_PROVISIONED',
  TENANT_ARCHIVED = 'TENANT_ARCHIVED',
  TENANT_PURGED = 'TENANT_PURGED',
  TENANT_MIGRATION_FAILED = 'TENANT_MIGRATION_FAILED',
  TENANT_JURISDICTION_MISMATCH = 'TENANT_JURISDICTION_MISMATCH',
