  TENANT_RESTORE_TOO_LARGE = 'TENANT_RESTORE_TOO_LARGE',
  TENANT_OPERATION_FAILED = 'TENANT_OPERATION_FAILED',
  TENANT_COMMAND_INVALID = 'TENANT_COMMAND_INVALID',
  TENANT_COMMAND_FINGERPRINT_MISMATCH = 'TENANT_COMMAND_FINGERPRINT_MISMATCH',
  TENANT_COMMAND_REPLY_INVALID = 'TENANT_COMMAND_REPLY_INVALID',
  TENANT_JOB_INVALID = 'TENANT_JOB_INVALID',
  TENANT_JOB_CALL_ONLY = 'TENANT_JOB_CALL_ONLY',
  TENANT_JOB_FAILED = 'TENANT_JOB_FAILED',
  TENANT_JOB_REPLY_INVALID = 'TENANT_JOB_REPLY_INVALID',
  TENANT_JOB_RESULT_INVALID = 'TENANT_JOB_RESULT_INVALID',
  TENANT_JOB_RESULT_TOO_LARGE = 'TENANT_JOB_RESULT_TOO_LARGE',
