/**
 * Structured error response
 */
export interface QuickbackError {
  /** Human-readable error message */
  error: string;

  /** Security layer that rejected the request */
  layer: QuickbackLayer;

  /** Machine-readable error code */
  code: QuickbackErrorCode;

  /** Additional context about the error */
  details?: {
    /** Required roles/permissions */
    required?: string[];

    /** Current user roles */
    current?: string[];

    /** Missing fields/values */
    missing?: string[];

    /** Offending fields: name → message. The same shape on every layer. */
    fields?: Record<string, string>;

    /** Available actions for protected fields */
    actions?: string[];

    /** Additional reason or context */
    reason?: string;

    /** Any other layer-specific data */
    [key: string]: any;
  };

  /** Optional developer hint for resolution */
  hint?: string;

  /**
   * Request context auto-attached by the global error-augmentation
   * middleware. Lets the error body alone be enough to triage or retry —
   * no log grep required. Bodies are capped and have well-known
   * sensitive fields (password, token, secret, otp, …) redacted.
   */
  request?: {
    /** HTTP method (GET, POST, PATCH, …) */
    method: string;
    /** Path + query string of the failing request */
    url: string;
    /** Truncated, redacted request body (omitted for GET/HEAD/DELETE) */
    body?: string;
    /** Correlation ID — matches the `x-request-id` response header and server log line */
    requestId?: string;
  };
}

/**
 * Create a structured error response
 */
export function createError(
  message: string,
  layer: QuickbackLayer,
  code: QuickbackErrorCode,
  details?: QuickbackError['details'],
  hint?: string
): QuickbackError {
  const error: QuickbackError = {
    error: message,
    layer,
    code,
  };

  if (details) {
    error.details = details;
  }

  if (hint) {
    error.hint = hint;
  }

  return error;
}

// ═══════════════════════════════════════════════════════════════════
// RFC 9457 Problem Details (application/problem+json) — the error contract.
// Maps a QuickbackError into the standard problem shape. The internal fields
// (code, layer, details, hint, request) survive as 9457 EXTENSION members —
// clients that switch on `code` keep working — while type/title/status/
// detail/instance make it a real Problem Details document any generic 9457
// client understands. `problemJson(c, err, status)` is the drop-in for the
// old `c.json(err, status)` error emission (Piece 2).
// ═══════════════════════════════════════════════════════════════════
const PROBLEM_BASE = 'https://quickback.dev/problems/';

/** Human-stable title from a code: VALIDATION_FAILED -> "Validation failed". */
function problemTitle(code: string): string {
  const s = code.toLowerCase().replace(/_/g, ' ');
  return s.charAt(0).toUpperCase() + s.slice(1);
}

export interface ProblemDetails {
  type: string;
  title: string;
  status: number;
  detail?: string;
  instance?: string;
  code?: string;
  [key: string]: any;
}

/** Build an RFC 9457 body from a QuickbackError-shaped object. */
export function toProblem(err: any, status: number, instance?: string): ProblemDetails {
  const code = String(err?.code ?? 'INTERNAL_ERROR');
  const problem: ProblemDetails = {
    type: PROBLEM_BASE + code.toLowerCase().replace(/_/g, '-'),
    title: problemTitle(code),
    status,
    code,
  };
  if (err?.error) problem.detail = err.error;
  // Compatibility extension member (#613): clients written against the
  // pre-0.70.4 { error, code } body read `error`, never `detail`. RFC 9457
  // §3.2 allows extension members; drop it with contract.errors.legacyErrorField: false.
  if (err?.error) problem.error = err.error;
  if (instance) problem.instance = instance;
  if (err?.layer) problem.layer = err.layer;
  if (err?.details) {
    problem.details = err.details;
    const first = Object.keys(err.details.fields ?? {})[0];
    if (first) problem.pointer = '/' + first;
  }
  if (err?.hint) problem.hint = err.hint;
  if (err?.request) problem.request = err.request;
  return problem;
}

/**
 * Emit an RFC 9457 response (application/problem+json). Drop-in replacement
 * for `c.json(err, status)` on error paths.
 */
export function problemJson(c: any, err: any, status: number): Response {
  let instance: string | undefined;
  try { instance = new URL(c.req.url).pathname; } catch { /* leave undefined */ }
  return new Response(JSON.stringify(toProblem(err, status, instance)), {
    status,
    headers: { 'Content-Type': 'application/problem+json' },
  });
}

